"""Single-page local review interface; no external assets or browser dependencies."""
PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>RECIST Clinical QC · Review workspace</title>
<style>
:root{font:16px system-ui,sans-serif;color:#1c3041;background:#f3f6f8;--accent:#086b70}*{box-sizing:border-box}body{margin:0}header{background:#163947;color:white;padding:26px max(24px,calc((100vw - 1160px)/2))}header p{color:#cae2e7;margin-bottom:0}h1{font-size:28px;margin:4px 0}h2{font-size:20px;margin:0 0 16px}h3{font-size:16px}main{max-width:1208px;margin:24px auto;padding:0 24px}.grid{display:grid;grid-template-columns:360px 1fr;gap:24px}.card{background:#fff;border:1px solid #dce4e9;border-radius:12px;padding:24px;margin-bottom:20px}p{line-height:1.6}.muted,small{color:#526572}label{display:block;font-weight:600;margin:16px 0 8px}select,input{font:inherit;width:100%;padding:10px;border:1px solid #a7b7c2;border-radius:6px}button,.button{font:inherit;padding:11px 16px;border:0;border-radius:6px;background:var(--accent);color:#fff;cursor:pointer;text-decoration:none;display:inline-block;margin:8px 8px 0 0}button.secondary,.button.secondary{background:#e5eff0;color:#125960}button:disabled{opacity:.5;cursor:wait}.badge{font-size:13px;padding:5px 10px;border-radius:20px;display:inline-block;background:#e7eef3}.ok{background:#e2f4e9;color:#14623a}.bad{background:#fbe9e6;color:#8b2a1a}.warn{background:#fff3d8;color:#795300}.metrics{display:flex;flex-wrap:wrap;gap:14px;margin:16px 0}.metric{background:#f2f6f8;padding:14px 20px;border-radius:8px;min-width:110px}.metric strong{display:block;font-size:26px}.scroll{overflow:auto;max-height:560px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:12px 10px;border-bottom:1px solid #dde5eb;text-align:left;vertical-align:top}th{background:#f4f7f9;position:sticky;top:0}details{padding:10px 0}summary{cursor:pointer;font-weight:600}a{color:#086b70}#message{margin:0 0 16px;padding:14px;border-radius:8px;background:#e6eff3}#message:empty{display:none}.notice{border-left:4px solid #d59d35;padding:12px 16px;background:#fff8e8;font-size:14px}.empty{text-align:center;padding:32px 8px}.step{font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#526572}.files a{display:block;margin:8px 0}.hidden,[hidden]{display:none!important}@media(max-width:850px){.grid{grid-template-columns:1fr}main{padding:0 12px}.card{padding:18px}header{padding:22px}}
.grid>*{min-width:0}button,select,input{max-width:100%}.files a,.notice,td{overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}@media print{header,aside,#message,#welcome,.files{display:none!important}.grid{display:block}.scroll{max-height:none;overflow:visible}.card{break-inside:avoid;box-shadow:none}body{background:white}main{margin:0;padding:0}}
</style></head><body>
<header><span class="step" style="color:#cae2e7">Measurement checks · Response review · Expected-output tests</span><h1>RECIST Clinical QC</h1><p>One workspace to try examples, review your CSV, and verify the calculated results.</p></header>
<main><div class="notice">Development review aid. Results are unconfirmed timepoint assessments; clinical and study-protocol validation are required. Use synthetic or de-identified files.</div><br>
<div class="grid"><aside>
<section class="card"><span class="step">1 · Choose data</span><h2>Start with a built-in example</h2><label for="example">Test scenario</label><select id="example"><option>Loading examples…</option></select>
<button id="runExample">Run selected example</button><a id="sampleDownload" class="button secondary" download>Download this CSV</a><p id="expected" class="muted"></p>
<hr><h3>Or upload your own CSV</h3><form id="upload"><label for="file">CSV file, maximum 2 MiB</label><input id="file" type="file" accept=".csv,text/csv" required><button>Run quality checks</button></form>
<p class="muted">CSV stays in memory. The app does not save uploaded files.</p></section>
<section class="card"><span class="step">2 · Verify the app</span><h2>Test expected results</h2><p>Check all built-in QC and response cases against fixed expected findings and categories.</p><button id="verify" class="secondary">Run all built-in tests</button><div id="verifySummary" role="status" aria-live="polite"></div><div id="verifyDetails"></div><p class="muted">These test results are included in the complete Excel workbook.</p></section>
<section class="card"><h2>Response input guide</h2><p>Use the measurement columns in the sample. For each follow-up, repeat these visit-level fields on every row:</p><ul><li><b>new_lesions:</b> yes, no, or unknown</li><li><b>non_target_response:</b> CR, NON_CR_NON_PD, PD, NE, or NOT_APPLICABLE</li><li><b>reported_response:</b> optional CR, PR, SD, PD, or NE</li></ul><p class="muted">Missing assessments are never assumed negative. NOT_APPLICABLE means no non-target disease. “Yes” for new lesions means unequivocal new disease. All baseline targets must be recorded at every follow-up.</p></section>
</aside><div>
<div id="message" role="status" aria-live="polite"></div>
<section class="card" id="welcome"><h2>Try the complete response example first</h2><p>Choose <b>RECIST responses and reported-response checks</b>, then click <b>Run selected example</b>.</p><p>You’ll see CR, PR, SD, PD, missing-information handling, and deliberately incorrect reported responses in one synthetic file. No downloads or command-line steps are needed to test these examples.</p></section>
<div id="review" hidden>
<section class="card"><span class="step">3 · Review data quality</span><h2 id="source"></h2><div class="metrics" id="metrics"></div><div id="dataStatus"></div><div class="scroll"><table id="findings" hidden><thead><tr><th>CSV row</th><th>Severity</th><th>Check</th><th>Explanation</th></tr></thead><tbody></tbody></table></div></section>
<section class="card"><span class="step">4 · Review responses</span><h2>Calculated vs reported responses</h2><p id="responseSummary"></p><div class="scroll"><table id="responses" hidden><thead><tr><th>Patient / visit</th><th>Target response</th><th>Overall response</th><th>Reported</th><th>Comparison</th><th>Measurements and explanation</th></tr></thead><tbody></tbody></table></div><h3 id="responseIssuesTitle" hidden>Response QC findings</h3><div id="responseIssues"></div><details><summary>What do the categories mean?</summary><p><b>CR:</b> complete response. <b>PR:</b> partial response. <b>SD:</b> stable disease. <b>PD:</b> progressive disease. <b>NE:</b> not evaluable.</p><p>Target PR: at least 30% decrease from baseline. Target PD: at least 20% increase and at least 5 mm increase from the prior nadir. Target CR: all non-nodal targets zero and target nodes below 10 mm short axis. New lesions or unequivocal non-target progression can make overall response PD.</p><p>These are timepoint calculations. Response confirmation, best overall response, non-target-only disease, imaging adequacy, and protocol-specific timing are outside this version. Missing non-target assessments conservatively yield NE unless valid progression evidence is present.</p></details></section>
<section class="card files"><span class="step">5 · Save the complete review</span><h2>One Excel report</h2><button id="excelDownload">Download complete Excel report</button><p class="muted">One .xlsx workbook with Summary, Input Data, Data QC, Responses, Response QC, Tests, and Notes tabs. Includes calculations, comparisons, explanations, and freshly run built-in test results. Empty findings tabs contain headers only.</p></section>
</div></div></div></main>
<script>
const $=s=>document.querySelector(s);let examples=[];let currentFile=null,currentName='';

function cell(row,text){const td=document.createElement('td');td.textContent=text??'—';row.append(td);return td;}

async function getJSON(url,options){const response=await fetch(url,options);const value=await response.json();if(!response.ok)throw Error(value.error||'Request failed');return value;}
function busy(value){document.querySelectorAll('button').forEach(b=>b.disabled=value);}
function sampleInfo(){const item=examples.find(x=>x.id===$('#example').value);if(!item)return;$('#sampleDownload').href='/api/examples/'+encodeURIComponent(item.id)+'.csv';$('#sampleDownload').download=item.id+'.csv';$('#expected').textContent=item.description;}
function show(report,name){$('#welcome').hidden=true;$('#review').hidden=false;$('#source').textContent=name;const qc=report.data_qc;$('#metrics').replaceChildren();for(const [label,value] of [['Rows',qc.rows_checked],['Errors',qc.errors],['Warnings',qc.warnings]]){const box=document.createElement('div');box.className='metric';const strong=document.createElement('strong');strong.textContent=value;box.append(strong,document.createTextNode(label));$('#metrics').append(box);}
 $('#dataStatus').textContent=qc.findings.length?'Review the findings below. Response calculations are held until data QC findings are resolved.':'Data checks passed. This does not establish clinical validity.';
 const body=$('#findings tbody');body.replaceChildren();for(const finding of qc.findings){const tr=document.createElement('tr');for(const key of ['row','severity','code','message'])cell(tr,finding[key]);body.append(tr);}$('#findings').hidden=!qc.findings.length;
 const review=report.response_review;$('#responseSummary').textContent=review.blocked_reason||`${review.assessments.length} follow-up assessments · ${review.response_qc.length} response QC findings. Missing reported responses are shown as “not supplied”.`;
 const responses=$('#responses tbody');responses.replaceChildren();for(const a of review.assessments){const tr=document.createElement('tr');cell(tr,a.patient_id+' / '+a.visit+' · '+a.assessment_date);cell(tr,a.target_response);cell(tr,a.overall_response);cell(tr,a.reported_response);cell(tr,a.comparison);const details=cell(tr,'');const p=document.createElement('p');p.textContent=a.sum_mm===null?'No calculation':`Sum ${a.sum_mm} mm · baseline ${a.baseline_sum_mm} mm · prior nadir ${a.prior_nadir_mm} mm · baseline change ${a.change_from_baseline_pct}% · nadir change ${a.change_from_nadir_pct===null?'undefined (zero nadir)':a.change_from_nadir_pct+'%'} · absolute nadir change ${a.increase_from_nadir_mm} mm`;const reason=document.createElement('p');reason.textContent=a.reason;details.append(p,reason);responses.append(tr);}$('#responses').hidden=!review.assessments.length;
 $('#responseIssues').replaceChildren();for(const finding of review.response_qc){const p=document.createElement('p');p.className='notice';p.textContent=finding.patient_id+' / '+finding.visit+' — '+finding.code+': '+finding.message;$('#responseIssues').append(p);}$('#responseIssuesTitle').hidden=!review.response_qc.length;

}
async function analyze(blob,name){busy(true);$('#message').textContent='Reviewing '+name+'…';try{if(blob.size>2097152)throw Error('File exceeds 2 MiB.');const report=await getJSON('/api/analyze',{method:'POST',headers:{'Content-Type':'text/csv'},body:blob});currentFile=blob;currentName=name;show(report,name);$('#message').textContent='Review complete. Check data findings, calculated responses, and reported-response comparisons below.';}catch(error){currentFile=null;$('#review').hidden=true;$('#message').textContent=error.message;}finally{busy(false);}}
$('#excelDownload').onclick=async()=>{if(!currentFile)return;busy(true);$('#message').textContent='Preparing the complete Excel workbook…';try{const response=await fetch('/api/export.xlsx',{method:'POST',headers:{'Content-Type':'text/csv','X-Source-Name':encodeURIComponent(currentName)},body:currentFile});if(!response.ok){const error=await response.json();throw Error(error.error||'Excel export failed');}const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download='complete-qc-report.xlsx';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('#message').textContent='Excel report downloaded. Open complete-qc-report.xlsx and start with the Summary tab.';}catch(error){$('#message').textContent=error.message;}finally{busy(false);}};
$('#example').onchange=sampleInfo;
$('#runExample').onclick=async()=>{const item=examples.find(x=>x.id===$('#example').value);try{const response=await fetch('/api/examples/'+encodeURIComponent(item.id)+'.csv');if(!response.ok)throw Error('Unable to load sample.');await analyze(await response.blob(),item.label);}catch(e){$('#message').textContent=e.message;}};
$('#upload').onsubmit=event=>{event.preventDefault();const file=$('#file').files[0];if(file)analyze(file,file.name);};
$('#verify').onclick=async()=>{busy(true);$('#verifySummary').textContent='Running expected-output checks…';try{const report=await getJSON('/api/self-test');$('#verifySummary').textContent=`${report.passed_count}/${report.total} built-in checks passed. ${report.passed?'Expected results matched.':'A test failed; review details before using results.'}`;const list=document.createElement('ul');for(const test of report.results){const li=document.createElement('li');li.textContent=(test.passed?'PASS: ':'FAIL: ')+test.label;if(!test.passed){const pre=document.createElement('pre');pre.textContent=JSON.stringify({expected:test.expected,actual:test.actual},null,2);li.append(pre);}list.append(li);}$('#verifyDetails').replaceChildren(list);}catch(e){$('#verifySummary').textContent=e.message;}finally{busy(false);}};
getJSON('/api/examples').then(data=>{examples=data;$('#example').replaceChildren();for(const example of examples){const option=document.createElement('option');option.value=example.id;option.textContent=example.label;$('#example').append(option);}sampleInfo();}).catch(error=>{$('#message').textContent='Could not load examples: '+error.message;});
</script></body></html>'''
